1	/*
2	 * CTAButton — padded-outline marketing CTA with a fixed shape end mark.
3	 *
4	 * ## behavior
5	 * - The end mark is a FIXED shape per size: the eight-leaf clover at
6	 *   `standard`, the puff at `big`. It is static: hover only rolls the label
7	 *   (RollHoverText on the root `.group`).
8	 * - The shape is painted with the OPPOSITE button's background: a primary CTA
9	 *   draws it in the secondary-button bg, a secondary CTA in the primary-button
10	 *   bg. The icon on it takes that button's content colour.
11	 * - Both sizes hug their content: 16px pill padding, a 60px label → mark gap,
12	 *   the label in `CTAText` (`.text-style-cta`: button role, semibold,
13	 *   24 / 28px).
14	 *
15	 * ## constraints
16	 * - The shape is chosen by `size`, never by a prop and never animated. That is
17	 *   the maintainer's decision (2026-10-03); a shape prop or a hover morph is a
18	 *   design change, not a refactor.
19	 * - The shapes are the `Shapes/` primitives, never re-drawn copies. Figma's
20	 *   flattened end-mark SVGs are not the source of truth.
21	 */
22	import { Slot } from "@radix-ui/react-slot";
23	import {
24	  cloneElement,
25	  forwardRef,
26	  isValidElement,
27	  type AnchorHTMLAttributes,
28	  type ForwardedRef,
29	  type ReactElement,
30	  type ReactNode,
31	  type RefAttributes,
32	} from "react";
33	import { cn } from "../../utils/cn";
34	import { RollHoverText } from "../AnimatedText";
35	import { EightLeafCloverShape, PuffShape } from "../Shapes";
36	import { CTAText } from "../Text";
37	import { CTAButtonSize, CTAButtonVariant } from "./constants";
38	
39	const SIZES = {
40	  standard: {
41	    content: "ds-gap-cta-content-standard ds-min-w-cta-content-standard pl-md",
42	    mark: "ds-size-cta-chip-standard",
43	    Shape: EightLeafCloverShape,
44	    shapeSize: "var(--ui-size-cta-shape-standard)",
45	    icon: "ds-size-cta-icon-standard",
46	    /* `.text-style-cta` is already sized for standard. */
47	    fontSize: undefined,
48	  },
49	  big: {
50	    content: "ds-gap-cta-content-big ds-min-w-cta-content-big pl-lg",
51	    mark: "ds-size-cta-chip-big",
52	    Shape: PuffShape,
53	    shapeSize: "var(--ui-size-cta-shape-big)",
54	    icon: "ds-size-cta-icon-big",
55	    fontSize: "var(--ui-text-cta-big)",
56	  },
57	} as const;
58	
59	/** Per variant: pill fill, label colour, shape paint, icon colour. */
60	const PAINTS = {
61	  primary: {
62	    pill: "bg-primary",
63	    label: "text-primary-fg",
64	    shape: "text-secondary",
65	    icon: "text-secondary-fg",
66	  },
67	  secondary: {
68	    pill: "bg-secondary",
69	    label: "text-secondary-fg",
70	    shape: "text-primary",
71	    icon: "text-primary-fg",
72	  },
73	} as const satisfies Record<CTAButtonVariant, Record<string, string>>;
74	
75	export interface CTAButtonProps
76	  extends Omit<AnchorHTMLAttributes<HTMLAnchorElement>, "children"> {
77	  /** Label shown in the CTA text style + RollHoverText. */
78	  text: string;
79	  /** Icon centred on the end-mark shape. */
80	  icon: ReactNode;
81	  /** Also picks the end-mark shape: eight-leaf clover (standard) or puff (big). */
82	  size?: CTAButtonSize;
83	  variant?: CTAButtonVariant;
84	  /**
85	   * Merge props onto the single child instead of rendering an `<a>`.
86	   * Use with Next.js `Link` (leave the Link empty — CTAButton supplies content):
87	   * `<CTAButton asChild text="…" icon={…}><Link href="/pricing" /></CTAButton>`
88	   */
89	  asChild?: boolean;
90	  /**
91	   * Read only with `asChild`: the single element CTAButton slots onto (its own
92	   * children are replaced by the CTA content). Without `asChild` there is no
93	   * place to render children — pass the label as `text`.
94	   */
95	  children?: ReactNode;
96	}
97	
98	/* Public call signatures: `children` type-checks only together with
99	 * `asChild`, so a label passed as children in anchor mode (which renders
100	 * nothing) is a compile error rather than silently dropped. Overloads rather
101	 * than a union keep `CTAButtonProps` extendable by consumer interfaces. */
102	type CTAButtonComponent = {
103	  (
104	    props: Omit<CTAButtonProps, "asChild" | "children"> & {
105	      asChild: true;
106	      children: ReactElement;
107	    } & RefAttributes<HTMLElement>,
108	  ): ReactElement | null;
109	  /* A runtime boolean (`asChild={isLink}`) needs an element child to slot onto. */
110	  (
111	    props: Omit<CTAButtonProps, "asChild" | "children"> & {
112	      asChild: boolean;
113	      children: ReactElement;
114	    } & RefAttributes<HTMLElement>,
115	  ): ReactElement | null;
116	  /* Anchor mode — listed LAST because ComponentProps (and so Storybook's
117	   * Meta<typeof CTAButton>) reads the last call signature. */
118	  (
119	    props: Omit<CTAButtonProps, "asChild" | "children"> & {
120	      asChild?: false;
121	      children?: never;
122	    } & RefAttributes<HTMLElement>,
123	  ): ReactElement | null;
124	  displayName?: string;
125	};
126	
127	/**
128	 * Padded-outline marketing CTA. The outline ring is primary-only; hover response
129	 * is label-only via RollHoverText on an ancestor `.group`. Radii stay fully round.
130	 */
131	const CTAButtonBase = forwardRef<HTMLElement, CTAButtonProps>(
132	  (
133	    {
134	      text,
135	      icon,
136	      size = CTAButtonSize.standard,
137	      variant = CTAButtonVariant.primary,
138	      asChild = false,
139	      className,
140	      children,
141	      ...props
142	    },
143	    ref,
144	  ) => {
145	    const s = SIZES[size];
146	    const paint = PAINTS[variant];
147	    const isPrimary = variant === CTAButtonVariant.primary;
148	    const Shape = s.Shape;
149	
150	    const content = (
151	      <span
152	        className={cn(
153	          "flex items-center p-lg",
154	          "rounded-full",
155	          "ds-drop-shadow-cta",
156	          paint.pill,
157	        )}
158	      >
159	        <span className={cn("flex items-center", s.content)}>
160	          <CTAText
161	            fontSize={s.fontSize}
162	            className={cn("min-w-px flex-1", paint.label)}
163	          >
164	            <RollHoverText>{text}</RollHoverText>
165	          </CTAText>
166	
167	          <span
168	            className={cn(
169	              "relative flex shrink-0 items-center justify-center",
170	              s.mark,
171	            )}
172	          >
173	            <span
174	              aria-hidden
175	              className={cn(
176	                "absolute inset-0 flex items-center justify-center",
177	                paint.shape,
178	              )}
179	            >
180	              <Shape
181	                size={s.shapeSize}
182	                strokeColor="transparent"
183	                strokeWeight={0}
184	                fillColor="currentColor"
185	              />
186	            </span>
187	            <span
188	              className={cn(
189	                "relative shrink-0 overflow-clip",
190	                s.icon,
191	                paint.icon,
192	              )}
193	            >
194	              {icon}
195	            </span>
196	          </span>
197	        </span>
198	      </span>
199	    );
200	
201	    const rootClassName = cn(
202	      "group inline-flex items-center justify-center p-sm",
203	      "rounded-full",
204	      "ds-focus-visible-ring",
205	      isPrimary && "border-2 border-solid border-border-cta",
206	      className,
207	    );
208	
209	    if (asChild) {
210	      if (!isValidElement(children)) {
211	        throw new Error(
212	          "CTAButton: asChild requires a single valid React element child.",
213	        );
214	      }
215	      return (
216	        <Slot ref={ref} className={rootClassName} {...props}>
217	          {cloneElement(children as ReactElement, undefined, content)}
218	        </Slot>
219	      );
220	    }
221	
222	    return (
223	      /* this branch always renders an <a>; the HTMLElement ref type is for asChild */
224	      <a
225	        ref={ref as ForwardedRef<HTMLAnchorElement>}
226	        className={rootClassName}
227	        {...props}
228	      >
229	        {content}
230	      </a>
231	    );
232	  },
233	);
234	CTAButtonBase.displayName = "CTAButton";
235	
236	const CTAButton = CTAButtonBase as CTAButtonComponent;
237	
238	export { CTAButton };
239

1	import type { Meta, StoryObj } from "@storybook/react-vite";
2	import { ChevronsRightIcon } from "../Icons";
